from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    points = [(r, c) for r in range(h) for c in range(w) if grid[r][c] != bg]
    if not points:
        return [row[:] for row in grid]
    r0 = min(r for r, c in points)
    r1 = max(r for r, c in points)
    c0 = min(c for r, c in points)
    c1 = max(c for r, c in points)
    out = [row[:] for row in grid]

    # Complete the perimeter of the foreground bounding box.
    for c in range(c0, c1 + 1):
        for r in (r0, r1):
            if out[r][c] == bg:
                out[r][c] = 2
    for r in range(r0, r1 + 1):
        for c in (c0, c1):
            if out[r][c] == bg:
                out[r][c] = 2

    # Complete internal aligned runs only when at least two foreground marks
    # lie strictly inside the box on that row/column. Edge marks can extend
    # the run, but do not by themselves trigger it.
    for c in range(c0 + 1, c1):
        internal = [r for r in range(r0 + 1, r1) if grid[r][c] != bg]
        if len(internal) >= 2:
            all_marks = [r for r in range(r0, r1 + 1) if grid[r][c] != bg]
            for r in range(min(all_marks), max(all_marks) + 1):
                if out[r][c] == bg:
                    out[r][c] = 2
    for r in range(r0 + 1, r1):
        internal = [c for c in range(c0 + 1, c1) if grid[r][c] != bg]
        if len(internal) >= 2:
            all_marks = [c for c in range(c0, c1 + 1) if grid[r][c] != bg]
            for c in range(min(all_marks), max(all_marks) + 1):
                if out[r][c] == bg:
                    out[r][c] = 2
    return out
